import { randomBytes } from 'crypto';
import fs from 'fs';
import path from 'path';
import { isDestinationEmpty } from '../services/templates/viteReactTs';
import type { ErrorCode } from './errors';

const SLUG_SUFFIX_BYTES = 2;

export const slugifyPrompt = (prompt: string): string => {
  const base = prompt
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40);
  const suffix = randomBytes(SLUG_SUFFIX_BYTES).toString('hex');
  return base ? `${base}-${suffix}` : `rivet-app-${suffix}`;
};

export const normalizeWorkspaceRoot = (candidate: string): string => {
  const resolved = path.resolve(candidate);
  const segments = resolved.split(path.sep);
  const index = segments.indexOf('.rivet');
  if (index <= 0) return resolved;
  return segments.slice(0, index).join(path.sep) || path.sep;
};

export interface GeneratedDestination {
  slug: string;
  workspaceRoot: string;
  destinationPath: string;
}

export interface DeriveDestinationFailure {
  errorCode: ErrorCode;
  message: string;
}

export type DeriveGeneratedDestinationResult =
  | ({ ok: true } & GeneratedDestination)
  | ({ ok: false } & DeriveDestinationFailure);

export function deriveGeneratedDestination(args: {
  prompt: string;
  destinationParent?: string;
  editorProjectPath?: string;
  cwd?: () => string;
  destinationIsEmpty?: (destinationPath: string) => boolean;
  mkdir?: (dir: string) => void;
}): DeriveGeneratedDestinationResult {
  const destinationParent =
    args.destinationParent ?? args.editorProjectPath ?? (args.cwd ?? process.cwd)();
  if (!path.isAbsolute(destinationParent)) {
    return {
      ok: false,
      errorCode: 'SCHEMA_VALIDATION_FAILED',
      message: `destinationParent must be absolute; got '${destinationParent}'.`,
    };
  }

  const slug = slugifyPrompt(args.prompt);
  const workspaceRoot = normalizeWorkspaceRoot(destinationParent);
  const destinationPath = path.join(workspaceRoot, '.rivet', slug);
  const isEmpty = args.destinationIsEmpty ?? isDestinationEmpty;

  if (!isEmpty(destinationPath)) {
    return {
      ok: false,
      errorCode: 'DESTINATION_NOT_EMPTY',
      message: `Destination '${destinationPath}' is not empty.`,
    };
  }

  const mkdir =
    args.mkdir ?? ((dir: string) => fs.mkdirSync(dir, { recursive: true }));
  mkdir(path.dirname(destinationPath));

  return { ok: true, slug, workspaceRoot, destinationPath };
}
